<?php
$q=trim((string)($_GET['q']??''));$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));$status=trim((string)($_GET['status']??''));$pageNo=max(1,(int)($_GET['p']??1));$perPage=10;
$where=['1=1'];$args=[];if($q!==''){$where[]='(t.kode_transaksi LIKE ? OR p.nama_pelanggan LIKE ?)';array_push($args,"%$q%","%$q%");}if($from!==''){$where[]='DATE(t.tanggal_transaksi)>=?';$args[]=$from;}if($to!==''){$where[]='DATE(t.tanggal_transaksi)<=?';$args[]=$to;}if(in_array($status,['lunas','belum_bayar','menunggu','gagal','dikembalikan'],true)){$where[]='t.status_pembayaran=?';$args[]=$status;}
$whereSql='WHERE '.implode(' AND ',$where);$count=$db->prepare("SELECT COUNT(*) FROM tbl_transaksi t LEFT JOIN tbl_pelanggan p ON p.id_pelanggan=t.id_pelanggan {$whereSql}");$count->execute($args);$total=(int)$count->fetchColumn();$offset=($pageNo-1)*$perPage;
$stmt=$db->prepare("SELECT t.*,COALESCE(p.nama_pelanggan,'Pelanggan Umum') nama_pelanggan,u.nama_lengkap nama_kasir FROM tbl_transaksi t LEFT JOIN tbl_pelanggan p ON p.id_pelanggan=t.id_pelanggan LEFT JOIN tbl_pengguna u ON u.id_pengguna=t.id_kasir {$whereSql} ORDER BY t.tanggal_transaksi DESC LIMIT {$perPage} OFFSET {$offset}");$stmt->execute($args);$rows=$stmt->fetchAll();
$sum=$db->prepare("SELECT COALESCE(SUM(CASE WHEN t.status_pembayaran='lunas' AND t.status_pesanan<>'dibatalkan' THEN t.total_belanja ELSE 0 END),0) FROM tbl_transaksi t LEFT JOIN tbl_pelanggan p ON p.id_pelanggan=t.id_pelanggan {$whereSql}");$sum->execute($args);$totalSales=(float)$sum->fetchColumn();
$params=['q'=>$q,'from'=>$from,'to'=>$to,'status'=>$status];
?>
<div class="page-heading"><div><span class="section-kicker">ANALISIS PENJUALAN</span><h1>Laporan Penjualan</h1><p>Pantau transaksi, cari nota, dan cetak ulang struk belanja.</p></div><div class="heading-actions"><span class="report-total"><small>Total penjualan sesuai filter</small><b><?=money($totalSales)?></b></span></div></div>
<div class="panel-card"><div class="filter-toolbar report-filter"><form method="get" class="report-form"><input type="hidden" name="page" value="reports"><div class="search-box"><i class="bi bi-search"></i><input type="search" name="q" value="<?=e($q)?>" placeholder="Cari nama pelanggan / no. transaksi"></div><input class="form-control" type="date" name="from" value="<?=e($from)?>" aria-label="Dari tanggal"><input class="form-control" type="date" name="to" value="<?=e($to)?>" aria-label="Sampai tanggal"><select class="form-select" name="status"><option value="">Semua pembayaran</option><?php foreach(['lunas'=>'Lunas','belum_bayar'=>'Belum Bayar','menunggu'=>'Menunggu','gagal'=>'Gagal','dikembalikan'=>'Dikembalikan'] as $v=>$label):?><option value="<?=$v?>" <?=$status===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select><button class="btn btn-dark-soft">Terapkan</button><a class="btn btn-light" href="<?=e(url('reports'))?>">Reset</a></form><span class="result-count"><?=$total?> transaksi</span></div>
<div class="table-responsive"><table class="table app-table align-middle"><thead><tr><th>No. Transaksi</th><th>Pelanggan</th><th>Waktu</th><th>Kasir</th><th>Metode</th><th>Total</th><th>Pembayaran</th><th>Pesanan</th><th class="text-end">Nota</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="9" class="empty-state">Tidak ada transaksi sesuai filter.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><b class="small"><?=e($r['kode_transaksi'])?></b><small class="d-block text-muted"><?=e(ucfirst($r['jenis_transaksi']))?></small></td><td><?=e($r['nama_pelanggan'])?></td><td><?=e(date('d/m/Y H:i',strtotime($r['tanggal_transaksi'])))?></td><td><?=e($r['nama_kasir']?:'-')?></td><td><?=e(strtoupper($r['metode_pembayaran']?:'-'))?></td><td class="fw-semibold"><?=money($r['total_belanja'])?></td><td><?=status_badge($r['status_pembayaran'])?></td><td><form method="post" class="d-flex gap-1 align-items-center"><?=Csrf::field()?><input type="hidden" name="action" value="update_order_status"><input type="hidden" name="_return" value="reports"><input type="hidden" name="id_transaksi" value="<?=$r['id_transaksi']?>"><select class="form-select form-select-sm status-select" name="status_pesanan"><?php foreach(['menunggu','diproses','siap_diambil','selesai','dibatalkan'] as $st):?><option value="<?=$st?>" <?=$r['status_pesanan']===$st?'selected':''?>><?=ucwords(str_replace('_',' ',$st))?></option><?php endforeach;?></select><button class="btn btn-sm btn-light" title="Simpan status"><i class="bi bi-check2"></i></button></form></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="<?=e(url('receipt',['id'=>$r['id_transaksi']]))?>" target="_blank"><i class="bi bi-printer me-1"></i>Cetak</a></td></tr><?php endforeach;?></tbody></table></div><div class="panel-footer"><span class="text-muted small">Halaman <?=$pageNo?> · Data dapat dicari berdasarkan nama pelanggan dan kode transaksi.</span><?php pagination($total,$pageNo,$perPage,'reports',$params);?></div></div>
